16	pub fn handle(args: AddArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
17	    let runner = CliCommandRunner;
18	    let ws = load_workspace(global, &runner)?;
19	
20	    let mut entries = Vec::new();
21	    let mut summary = args.summary.clone();
22	
23	    if !args.packages.is_empty() {
24	        // Non-interactive mode (flags supplied via CLI or agent)
25	        for pkg_str in args.packages {
26	            let (name, sev_str) = pkg_str
27	                .rsplit_once(':')
28	                .ok_or_else(|| CliError::AddInvalidPackageSpec { spec: pkg_str.clone() })?;
29	
30	            let severity = parse_severity(sev_str)?;
31	
32	            // Resolves by any registered native name (not just a package's
33	            // primary/display name), reporting E102/E103 on a miss or
34	            // ecosystem-ambiguous bare name.
35	            callisto_graph::ConfigError::require_qualified(name, "--package")
36	                .map_err(callisto_graph::GraphError::Config)?;
37	            let resolved = ws.identity.resolve(name)?;
38	
39	            entries.push(Entry {
40	                // Use display_name() so "cargo/foo" is preserved, not just "foo".
41	                // In a polyglot workspace, the bare name is ambiguous across ecosystems.
42	                name: resolved.display_name(),
43	                severity,
44	            });
45	        }
46	    } else if tty::is_interactive() {
47	        let all_packages = collect_package_names(ws.graph.packages());
48	        let Some((chosen, written)) = run_wizard(&all_packages, summary.clone(), &mut TerminalAddPrompter)? else {
49	            return Ok(ExitCode::SUCCESS);
50	        };
51	        entries = chosen;
52	        summary = Some(written);
53	    } else {
54	        return Err(CliError::NotATty);
55	    }
56	
57	    let raw_summary = summary.ok_or(CliError::AddSummaryRequired)?;
58	    let summary_text = validate_summary(&raw_summary)?;
59	    let changeset = Changeset {
60	        entries,
61	        summary: summary_text,
62	    };
63	    let text = callisto_model::format::write_changeset(&changeset)?;
64	
65	    let changeset_dir = ws.root.join(&ws.config.changesets_dir);
66	
67	    let Some(permit) = ApplyPermit::granted_unless_dry_run(global.dry_run) else {
68	        // Compute what WOULD be written, but never touch disk.
69	        let filename = unused_changeset_filename(&changeset_dir)?;
70	        let rel_path = ws.config.changesets_dir.join(&filename).to_string_lossy().into_owned();
71	        match global.format {
72	            OutputFormat::Json => {
73	                let report = AddReport {
74	                    schema_version: SCHEMA_VERSION,
75	                    path: rel_path,
76	                    content: Some(text),
77	                    diagnostics: vec![],
78	                };
79	                emit_report(&mut std::io::stdout(), &report, true)?;
80	            }
81	            OutputFormat::Text => {
82	                emit_line(&format!(
83	                    "[DRY-RUN] Would add changeset: {rel_path} (no files written)\n\n{text}"
84	                ))?;
85	            }
86	        }
87	        return Ok(ExitCode::SUCCESS);
88	    };
89	
90	    fs::create_dir_all(&changeset_dir)?;
91	    let filename = create_changeset(&changeset_dir, &text, &permit, generate_human_slug)?;
92	    let rel_path = ws.config.changesets_dir.join(&filename).to_string_lossy().into_owned();
93	
94	    match global.format {
95	        OutputFormat::Json => {
96	            let report = AddReport {
97	                schema_version: SCHEMA_VERSION,
98	                path: rel_path,
99	                content: None,
100	                diagnostics: vec![],
101	            };
102	            emit_report(&mut std::io::stdout(), &report, false)?;
103	        }
104	        OutputFormat::Text => {
105	            log_line(global.format, &format!("Added changeset: {rel_path}"))?;
106	        }
107	    }
108	
109	    Ok(ExitCode::SUCCESS)
110	}
