144	/// The interactive five-step wizard (as in `@changesets/cli`): packages, which are major, which of the rest are minor
145	/// (the remainder default to patch), a summary unless one was given, then a preview to confirm. `None` when the
146	/// contributor declines the preview.
147	fn run_wizard(
148	    all_packages: &[String],
149	    summary: Option<String>,
150	    prompter: &mut impl AddPrompter,
151	) -> Result<Option<(Vec<Entry>, String)>, CliError> {
152	    if all_packages.is_empty() {
153	        return Err(CliError::AddNoPackagesInWorkspace);
154	    }
155	
156	    prompt_line("Which packages would you like to include in this changeset?");
157	    let selected_indices = prompter.multi_select(all_packages)?;
158	    if selected_indices.is_empty() {
159	        return Err(CliError::AddNoPackagesSelected);
160	    }
161	    let selected_packages: Vec<String> = selected_indices.into_iter().map(|i| all_packages[i].clone()).collect();
162	
163	    prompt_line("\nWhich of these packages should be a MAJOR bump?");
164	    prompt_line("(Select none if there are no breaking changes)");
165	    let major_set: std::collections::HashSet<usize> = prompter.multi_select(&selected_packages)?.into_iter().collect();
166	
167	    let minor_candidates: Vec<String> = selected_packages
168	        .iter()
169	        .enumerate()
170	        .filter(|(idx, _)| !major_set.contains(idx))
171	        .map(|(_, name)| name.clone())
172	        .collect();
173	    let minor_set: std::collections::HashSet<String> = if minor_candidates.is_empty() {
174	        std::collections::HashSet::new()
175	    } else {
176	        prompt_line("\nWhich of these packages should be a MINOR bump?");
177	        prompt_line("(Any remaining packages will default to a PATCH bump)");
178	        prompter
179	            .multi_select(&minor_candidates)?
180	            .into_iter()
181	            .map(|idx| minor_candidates[idx].clone())
182	            .collect()
183	    };
184	
185	    let entries: Vec<Entry> = selected_packages
186	        .iter()
187	        .enumerate()
188	        .map(|(idx, name)| Entry {
189	            name: name.clone(),
190	            severity: if major_set.contains(&idx) {
191	                Severity::Major
192	            } else if minor_set.contains(name) {
193	                Severity::Minor
194	            } else {
195	                Severity::Patch
196	            },
197	        })
198	        .collect();
199	
200	    let summary = match summary {
201	        Some(summary) => summary,
202	        None => {
203	            prompt_line("\nPlease enter a summary for this change:");
204	            prompter.summary()?
205	        }
206	    };
207	
208	    let preview = Changeset {
209	        entries: entries.clone(),
210	        summary: summary.clone(),
211	    };
212	    prompt_line(&format!(
213	        "\n=== Changeset Preview ===\n{}",
214	        callisto_model::format::write_changeset(&preview)?
215	    ));
216	    if !prompter.confirm("Is this your desired changeset?", true)? {
217	        prompt_line("Changeset creation cancelled.");
218	        return Ok(None);
219	    }
220	    Ok(Some((entries, summary)))
221	}
