252	/// Writes `text` to a new file in `dir` named by `next_slug`, trying another slug whenever the name is taken, including
253	/// by a changeset another process created after this one looked. Nothing already in `dir` is ever replaced.
254	fn create_changeset(
255	    dir: &std::path::Path,
256	    text: &str,
257	    permit: &ApplyPermit,
258	    mut next_slug: impl FnMut() -> String,
259	) -> Result<String, CliError> {
260	    // 8,000 possible slugs: more than a few attempts only happens when nearly all of them are taken.
261	    for _ in 0..64 {
262	        let filename = format!("{}.md", next_slug());
263	        let path = dir.join(&filename);
264	        match callisto_model::atomic::atomic_write_new(&path, text, permit) {
265	            Ok(()) => return Ok(filename),
266	            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {}
267	            Err(source) => {
268	                return Err(CliError::Io {
269	                    source,
270	                    path: Some(path),
271	                })
272	            }
273	        }
274	    }
275	    Err(CliError::Io {
276	        source: std::io::Error::new(
277	            std::io::ErrorKind::AlreadyExists,
278	            "no unused changeset filename found after 64 attempts",
279	        ),
280	        path: Some(dir.to_path_buf()),
281	    })
282	}
