284	/// Picks a changeset filename that does not exist yet, so a slug collision never overwrites a pending changeset.
285	fn unused_changeset_filename(dir: &std::path::Path) -> Result<String, CliError> {
286	    // 8,000 possible slugs: more than a few attempts only happens when nearly all of them are taken.
287	    for _ in 0..64 {
288	        let filename = format!("{}.md", generate_human_slug());
289	        let path = dir.join(&filename);
290	        let taken = callisto_model::strict_fs::exists(&path).map_err(|source| CliError::Io {
291	            source,
292	            path: Some(path.clone()),
293	        })?;
294	        if !taken {
295	            return Ok(filename);
296	        }
297	    }
298	    Err(CliError::Io {
299	        source: std::io::Error::new(
300	            std::io::ErrorKind::AlreadyExists,
301	            "no unused changeset filename found after 64 attempts",
302	        ),
303	        path: Some(dir.to_path_buf()),
304	    })
305	}
306	
307	fn generate_human_slug() -> String {
308	    use std::sync::atomic::{AtomicU64, Ordering};
309	
310	    static COUNTER: AtomicU64 = AtomicU64::new(0);
311	
312	    let adjectives = [
313	        "swift", "clever", "bright", "silent", "brave", "calm", "eager", "gentle", "happy", "jolly", "keen", "lively",
314	        "mighty", "noble", "proud", "quick", "radiant", "sharp", "tough", "vivid",
315	    ];
316	    let nouns = [
317	        "foxes", "hawks", "wolves", "eagles", "bears", "lions", "otters", "pandas", "falcons", "tigers", "dolphins",
318	        "panthers", "cheetahs", "leopards", "ravens", "badgers", "lynxes", "cobras", "owls", "stags",
319	    ];
320	    let verbs = [
321	        "run", "fly", "leap", "soar", "dash", "hunt", "glide", "climb", "swim", "roar", "pounce", "sprint", "chase",
322	        "race", "bound", "drift", "jump", "strut", "spin", "surge",
323	    ];
324	
325	    // Each word list has 20 entries; total combination space is 20^3 = 8,000.
326	    // We map consecutive counter values to unique triples via integer division:
327	    //   a = idx % 20, n = (idx / 20) % 20, v = (idx / 400) % 20
328	    // This is a bijection on {0..7999}, so 8,000 consecutive calls all yield
329	    // distinct slugs regardless of OS clock resolution.
330	    //
331	    // A timestamp-derived offset rotates the starting position across process
332	    // restarts so repeated runs don't produce the same slug sequence.
333	    let ts = std::time::SystemTime::now()
334	        .duration_since(std::time::UNIX_EPOCH)
335	        .map(|d| d.as_nanos() as u64)
336	        .unwrap_or(0);
337	
338	    let count = COUNTER.fetch_add(1, Ordering::Relaxed);
339	    // Shift ts right to get a slowly-varying cross-run offset (changes every ~1 µs).
340	    let offset = (ts >> 10) % 8000;
341	    let idx = (count + offset) % 8000;
342	
343	    let a = adjectives[(idx % 20) as usize];
344	    let n = nouns[((idx / 20) % 20) as usize];
345	    let v = verbs[((idx / 400) % 20) as usize];
346	
347	    format!("{a}-{n}-{v}")
348	}
