use std::fs;
use std::process::ExitCode;

use callisto_graph::DependencyResolver;
use callisto_model::format::{Changeset, Entry};
use callisto_model::{AddReport, ApplyPermit, Severity, SCHEMA_VERSION};
use dialoguer::{Confirm, Input, MultiSelect};

use crate::cli::{AddArgs, GlobalArgs, OutputFormat};
use crate::error::CliError;
use crate::output::{emit_line, emit_report, log_line, prompt_line};
use crate::runner::CliCommandRunner;
use crate::tty;
use crate::workspace::load_workspace;

pub fn handle(args: AddArgs, global: &GlobalArgs) -> Result<ExitCode, CliError> {
    let runner = CliCommandRunner;
    let ws = load_workspace(global, &runner)?;

    let mut entries = Vec::new();
    let mut summary = args.summary.clone();

    if !args.packages.is_empty() {
        // Non-interactive mode (flags supplied via CLI or agent)
        for pkg_str in args.packages {
            let (name, sev_str) = pkg_str
                .rsplit_once(':')
                .ok_or_else(|| CliError::AddInvalidPackageSpec { spec: pkg_str.clone() })?;

            let severity = parse_severity(sev_str)?;

            // Resolves by any registered native name (not just a package's
            // primary/display name), reporting E102/E103 on a miss or
            // ecosystem-ambiguous bare name.
            callisto_graph::ConfigError::require_qualified(name, "--package")
                .map_err(callisto_graph::GraphError::Config)?;
            let resolved = ws.identity.resolve(name)?;

            entries.push(Entry {
                // Use display_name() so "cargo/foo" is preserved, not just "foo".
                // In a polyglot workspace, the bare name is ambiguous across ecosystems.
                name: resolved.display_name(),
                severity,
            });
        }
    } else if tty::is_interactive() {
        let all_packages = collect_package_names(ws.graph.packages());
        let Some((chosen, written)) = run_wizard(&all_packages, summary.clone(), &mut TerminalAddPrompter)? else {
            return Ok(ExitCode::SUCCESS);
        };
        entries = chosen;
        summary = Some(written);
    } else {
        return Err(CliError::NotATty);
    }

    let raw_summary = summary.ok_or(CliError::AddSummaryRequired)?;
    let summary_text = validate_summary(&raw_summary)?;
    let changeset = Changeset {
        entries,
        summary: summary_text,
    };
    let text = callisto_model::format::write_changeset(&changeset)?;

    let changeset_dir = ws.root.join(&ws.config.changesets_dir);

    let Some(permit) = ApplyPermit::granted_unless_dry_run(global.dry_run) else {
        // Compute what WOULD be written, but never touch disk.
        let filename = unused_changeset_filename(&changeset_dir)?;
        let rel_path = ws.config.changesets_dir.join(&filename).to_string_lossy().into_owned();
        match global.format {
            OutputFormat::Json => {
                let report = AddReport {
                    schema_version: SCHEMA_VERSION,
                    path: rel_path,
                    content: Some(text),
                    diagnostics: vec![],
                };
                emit_report(&mut std::io::stdout(), &report, true)?;
            }
            OutputFormat::Text => {
                emit_line(&format!(
                    "[DRY-RUN] Would add changeset: {rel_path} (no files written)\n\n{text}"
                ))?;
            }
        }
        return Ok(ExitCode::SUCCESS);
    };

    fs::create_dir_all(&changeset_dir)?;
    let filename = create_changeset(&changeset_dir, &text, &permit, generate_human_slug)?;
    let rel_path = ws.config.changesets_dir.join(&filename).to_string_lossy().into_owned();

    match global.format {
        OutputFormat::Json => {
            let report = AddReport {
                schema_version: SCHEMA_VERSION,
                path: rel_path,
                content: None,
                diagnostics: vec![],
            };
            emit_report(&mut std::io::stdout(), &report, false)?;
        }
        OutputFormat::Text => {
            log_line(global.format, &format!("Added changeset: {rel_path}"))?;
        }
    }

    Ok(ExitCode::SUCCESS)
}

/// The wizard's questions; a scripted implementation drives tests.
trait AddPrompter {
    /// The indices the contributor ticked.
    fn multi_select(&mut self, items: &[String]) -> Result<Vec<usize>, CliError>;
    fn summary(&mut self) -> Result<String, CliError>;
    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError>;
}

struct TerminalAddPrompter;

impl AddPrompter for TerminalAddPrompter {
    fn multi_select(&mut self, items: &[String]) -> Result<Vec<usize>, CliError> {
        Ok(MultiSelect::new().items(items).interact()?)
    }

    fn summary(&mut self) -> Result<String, CliError> {
        Ok(Input::new()
            .validate_with(|input: &String| -> Result<(), &str> {
                if input.trim().is_empty() {
                    Err("Summary cannot be empty. Please enter a description of the change.")
                } else {
                    Ok(())
                }
            })
            .interact_text()?)
    }

    fn confirm(&mut self, prompt: &str, default: bool) -> Result<bool, CliError> {
        Ok(Confirm::new().with_prompt(prompt).default(default).interact()?)
    }
}

/// The interactive five-step wizard (as in `@changesets/cli`): packages, which are major, which of the rest are minor
/// (the remainder default to patch), a summary unless one was given, then a preview to confirm. `None` when the
/// contributor declines the preview.
fn run_wizard(
    all_packages: &[String],
    summary: Option<String>,
    prompter: &mut impl AddPrompter,
) -> Result<Option<(Vec<Entry>, String)>, CliError> {
    if all_packages.is_empty() {
        return Err(CliError::AddNoPackagesInWorkspace);
    }

    prompt_line("Which packages would you like to include in this changeset?");
    let selected_indices = prompter.multi_select(all_packages)?;
    if selected_indices.is_empty() {
        return Err(CliError::AddNoPackagesSelected);
    }
    let selected_packages: Vec<String> = selected_indices.into_iter().map(|i| all_packages[i].clone()).collect();

    prompt_line("\nWhich of these packages should be a MAJOR bump?");
    prompt_line("(Select none if there are no breaking changes)");
    let major_set: std::collections::HashSet<usize> = prompter.multi_select(&selected_packages)?.into_iter().collect();

    let minor_candidates: Vec<String> = selected_packages
        .iter()
        .enumerate()
        .filter(|(idx, _)| !major_set.contains(idx))
        .map(|(_, name)| name.clone())
        .collect();
    let minor_set: std::collections::HashSet<String> = if minor_candidates.is_empty() {
        std::collections::HashSet::new()
    } else {
        prompt_line("\nWhich of these packages should be a MINOR bump?");
        prompt_line("(Any remaining packages will default to a PATCH bump)");
        prompter
            .multi_select(&minor_candidates)?
            .into_iter()
            .map(|idx| minor_candidates[idx].clone())
            .collect()
    };

    let entries: Vec<Entry> = selected_packages
        .iter()
        .enumerate()
        .map(|(idx, name)| Entry {
            name: name.clone(),
            severity: if major_set.contains(&idx) {
                Severity::Major
            } else if minor_set.contains(name) {
                Severity::Minor
            } else {
                Severity::Patch
            },
        })
        .collect();

    let summary = match summary {
        Some(summary) => summary,
        None => {
            prompt_line("\nPlease enter a summary for this change:");
            prompter.summary()?
        }
    };

    let preview = Changeset {
        entries: entries.clone(),
        summary: summary.clone(),
    };
    prompt_line(&format!(
        "\n=== Changeset Preview ===\n{}",
        callisto_model::format::write_changeset(&preview)?
    ));
    if !prompter.confirm("Is this your desired changeset?", true)? {
        prompt_line("Changeset creation cancelled.");
        return Ok(None);
    }
    Ok(Some((entries, summary)))
}

/// Parses a CLI-supplied severity string, reporting every value `Severity`
/// actually accepts (`none`, `patch`, `minor`, `major`) on failure -- not a
/// stale subset that omits `none`.
fn parse_severity(sev_str: &str) -> Result<Severity, CliError> {
    sev_str.parse().map_err(|_err| CliError::InvalidSeverity {
        value: sev_str.to_string(),
    })
}

/// Validates that a changeset summary string is non-empty and non-whitespace.
///
/// Returns `Ok(trimmed_summary)` on success, or a [`CliError`] with a user-facing message.
fn validate_summary(summary: &str) -> Result<String, CliError> {
    let trimmed = summary.trim().to_string();
    if trimmed.is_empty() {
        return Err(CliError::AddSummaryEmpty);
    }
    Ok(trimmed)
}

/// Builds the list of package names shown in the interactive multiselect wizard.
///
/// Uses `.display_name()` so that packages sharing a bare name across different
/// ecosystems (e.g. `cargo/foo` and `npm/foo`) appear as distinct, qualified
/// entries in the list rather than two identical `"foo"` rows.
fn collect_package_names<'a>(packages: impl Iterator<Item = &'a callisto_model::Package>) -> Vec<String> {
    packages.map(|p| p.id.display_name()).collect()
}

/// Writes `text` to a new file in `dir` named by `next_slug`, trying another slug whenever the name is taken, including
/// by a changeset another process created after this one looked. Nothing already in `dir` is ever replaced.
fn create_changeset(
    dir: &std::path::Path,
    text: &str,
    permit: &ApplyPermit,
    mut next_slug: impl FnMut() -> String,
) -> Result<String, CliError> {
    // 8,000 possible slugs: more than a few attempts only happens when nearly all of them are taken.
    for _ in 0..64 {
        let filename = format!("{}.md", next_slug());
        let path = dir.join(&filename);
        match callisto_model::atomic::atomic_write_new(&path, text, permit) {
            Ok(()) => return Ok(filename),
            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {}
            Err(source) => {
                return Err(CliError::Io {
                    source,
                    path: Some(path),
                })
            }
        }
    }
    Err(CliError::Io {
        source: std::io::Error::new(
            std::io::ErrorKind::AlreadyExists,
            "no unused changeset filename found after 64 attempts",
        ),
        path: Some(dir.to_path_buf()),
    })
}

/// Picks a changeset filename that does not exist yet, so a slug collision never overwrites a pending changeset.
fn unused_changeset_filename(dir: &std::path::Path) -> Result<String, CliError> {
    // 8,000 possible slugs: more than a few attempts only happens when nearly all of them are taken.
    for _ in 0..64 {
        let filename = format!("{}.md", generate_human_slug());
        let path = dir.join(&filename);
        let taken = callisto_model::strict_fs::exists(&path).map_err(|source| CliError::Io {
            source,
            path: Some(path.clone()),
        })?;
        if !taken {
            return Ok(filename);
        }
    }
    Err(CliError::Io {
        source: std::io::Error::new(
            std::io::ErrorKind::AlreadyExists,
            "no unused changeset filename found after 64 attempts",
        ),
        path: Some(dir.to_path_buf()),
    })
}

fn generate_human_slug() -> String {
    use std::sync::atomic::{AtomicU64, Ordering};

    static COUNTER: AtomicU64 = AtomicU64::new(0);

    let adjectives = [
        "swift", "clever", "bright", "silent", "brave", "calm", "eager", "gentle", "happy", "jolly", "keen", "lively",
        "mighty", "noble", "proud", "quick", "radiant", "sharp", "tough", "vivid",
    ];
    let nouns = [
        "foxes", "hawks", "wolves", "eagles", "bears", "lions", "otters", "pandas", "falcons", "tigers", "dolphins",
        "panthers", "cheetahs", "leopards", "ravens", "badgers", "lynxes", "cobras", "owls", "stags",
    ];
    let verbs = [
        "run", "fly", "leap", "soar", "dash", "hunt", "glide", "climb", "swim", "roar", "pounce", "sprint", "chase",
        "race", "bound", "drift", "jump", "strut", "spin", "surge",
    ];

    // Each word list has 20 entries; total combination space is 20^3 = 8,000.
    // We map consecutive counter values to unique triples via integer division:
    //   a = idx % 20, n = (idx / 20) % 20, v = (idx / 400) % 20
    // This is a bijection on {0..7999}, so 8,000 consecutive calls all yield
    // distinct slugs regardless of OS clock resolution.
    //
    // A timestamp-derived offset rotates the starting position across process
    // restarts so repeated runs don't produce the same slug sequence.
    let ts = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(0);

    let count = COUNTER.fetch_add(1, Ordering::Relaxed);
    // Shift ts right to get a slowly-varying cross-run offset (changes every ~1 µs).
    let offset = (ts >> 10) % 8000;
    let idx = (count + offset) % 8000;

    let a = adjectives[(idx % 20) as usize];
    let n = nouns[((idx / 20) % 20) as usize];
    let v = verbs[((idx / 400) % 20) as usize];

    format!("{a}-{n}-{v}")
}

#[cfg(test)]
mod tests {
    use super::*;
    use callisto_model::{ManifestDecl, ManifestFormat, ManifestRole, Package, PackageId, ReleaseTrigger};
    use std::collections::HashSet;
    use std::path::PathBuf;

    /// Answers the wizard from a script: each multi-select, then the summary, then the confirmation.
    #[derive(Default)]
    struct Scripted {
        selections: std::collections::VecDeque<Vec<usize>>,
        summary: Option<String>,
        confirm: bool,
        /// The items each multi-select was shown, in order.
        shown: Vec<Vec<String>>,
        summary_asked: bool,
    }

    impl AddPrompter for Scripted {
        fn multi_select(&mut self, items: &[String]) -> Result<Vec<usize>, CliError> {
            self.shown.push(items.to_vec());
            Ok(self.selections.pop_front().expect("an unexpected multi-select"))
        }

        fn summary(&mut self) -> Result<String, CliError> {
            self.summary_asked = true;
            Ok(self.summary.clone().expect("an unexpected summary prompt"))
        }

        fn confirm(&mut self, _prompt: &str, _default: bool) -> Result<bool, CliError> {
            Ok(self.confirm)
        }
    }

    fn names(names: &[&str]) -> Vec<String> {
        names.iter().map(|name| (*name).to_owned()).collect()
    }

    fn severities(entries: &[Entry]) -> Vec<(&str, Severity)> {
        entries
            .iter()
            .map(|entry| (entry.name.as_str(), entry.severity))
            .collect()
    }

    #[test]
    fn the_wizard_gives_majors_then_minors_and_defaults_the_rest_to_patch() {
        let mut prompter = Scripted {
            selections: [vec![0, 1, 2], vec![0], vec![0]].into(),
            summary: Some("Rework the API".to_owned()),
            confirm: true,
            ..Default::default()
        };
        let (entries, summary) = run_wizard(&names(&["cargo/a", "cargo/b", "cargo/c"]), None, &mut prompter)
            .unwrap()
            .expect("confirmed");
        assert_eq!(
            severities(&entries),
            [
                ("cargo/a", Severity::Major),
                ("cargo/b", Severity::Minor),
                ("cargo/c", Severity::Patch)
            ]
        );
        assert_eq!(summary, "Rework the API");
        // The minor question is only about the packages that are not already major.
        assert_eq!(prompter.shown[2], names(&["cargo/b", "cargo/c"]));
    }

    #[test]
    fn the_wizard_only_offers_the_packages_that_were_selected_for_the_bump_questions() {
        let mut prompter = Scripted {
            selections: [vec![2, 0], vec![], vec![]].into(),
            summary: Some("Fix".to_owned()),
            confirm: true,
            ..Default::default()
        };
        let (entries, _) = run_wizard(&names(&["cargo/a", "cargo/b", "cargo/c"]), None, &mut prompter)
            .unwrap()
            .expect("confirmed");
        assert_eq!(
            severities(&entries),
            [("cargo/c", Severity::Patch), ("cargo/a", Severity::Patch)]
        );
        assert_eq!(prompter.shown[1], names(&["cargo/c", "cargo/a"]));
    }

    #[test]
    fn when_every_package_is_major_there_is_no_minor_question() {
        let mut prompter = Scripted {
            selections: [vec![0, 1], vec![0, 1]].into(),
            summary: Some("Breaking".to_owned()),
            confirm: true,
            ..Default::default()
        };
        run_wizard(&names(&["cargo/a", "cargo/b"]), None, &mut prompter).unwrap();
        assert_eq!(prompter.shown.len(), 2, "no third multi-select");
    }

    #[test]
    fn a_summary_given_on_the_command_line_is_not_asked_for_again() {
        let mut prompter = Scripted {
            selections: [vec![0], vec![], vec![]].into(),
            confirm: true,
            ..Default::default()
        };
        let (_, summary) = run_wizard(&names(&["cargo/a"]), Some("From the flag".to_owned()), &mut prompter)
            .unwrap()
            .expect("confirmed");
        assert_eq!(summary, "From the flag");
        assert!(!prompter.summary_asked);
    }

    #[test]
    fn declining_the_preview_cancels_without_a_changeset() {
        let mut prompter = Scripted {
            selections: [vec![0], vec![], vec![]].into(),
            summary: Some("Never mind".to_owned()),
            confirm: false,
            ..Default::default()
        };
        assert!(run_wizard(&names(&["cargo/a"]), None, &mut prompter).unwrap().is_none());
    }

    #[test]
    fn a_workspace_with_no_packages_and_a_selection_of_none_are_errors_with_their_own_message() {
        let mut prompter = Scripted::default();
        assert!(matches!(
            run_wizard(&[], None, &mut prompter),
            Err(CliError::AddNoPackagesInWorkspace)
        ));
        let mut prompter = Scripted {
            selections: [vec![]].into(),
            ..Default::default()
        };
        assert!(matches!(
            run_wizard(&names(&["cargo/a"]), None, &mut prompter),
            Err(CliError::AddNoPackagesSelected)
        ));
    }

    /// Constructs a minimal `Package` for a given id string (e.g. `"cargo/foo"`).
    fn make_package(id_str: &str) -> Package {
        let id = PackageId::parse(id_str).unwrap();
        let decl = ManifestDecl::new(
            PathBuf::from(format!("{}/Cargo.toml", id.name())),
            ManifestRole::Canonical,
            ManifestFormat::CargoToml,
        )
        .unwrap();
        Package {
            id,
            manifests: vec![decl],
            changelog: None,
            release_trigger: ReleaseTrigger::Changeset,
            publish_to: vec![],
            tag_template: None,
        }
    }

    /// Non-interactive mode with an empty --summary must fail with a clear error before
    /// reaching write_changeset, not silently write a file with an empty summary.
    #[test]
    fn non_interactive_empty_summary_is_rejected() {
        let result = validate_summary("");
        assert!(result.is_err(), "empty summary should be rejected");
    }

    #[test]
    fn non_interactive_whitespace_summary_is_rejected() {
        let result = validate_summary("   \t\n  ");
        assert!(result.is_err(), "whitespace-only summary should be rejected");
    }

    #[test]
    fn non_interactive_nonempty_summary_is_accepted() {
        let result = validate_summary("Fix a bug in the parser");
        assert!(result.is_ok(), "non-empty summary should be accepted");
        assert_eq!(result.unwrap(), "Fix a bug in the parser");
    }

    #[test]
    fn validate_summary_trims_leading_and_trailing_whitespace() {
        let result = validate_summary("  important fix  ");
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), "important fix");
    }

    /// Bug 3: the invalid-severity error message must list every value
    /// `Severity::from_str` actually accepts, including `none` -- not just
    /// patch/minor/major.
    #[test]
    fn parse_severity_rejects_invalid_value_with_accurate_message() {
        let err = parse_severity("bogus").unwrap_err();
        assert_eq!(
            err.to_string(),
            "Invalid severity `bogus`. Must be none, patch, minor, or major."
        );
    }

    #[test]
    fn parse_severity_accepts_none() {
        assert_eq!(parse_severity("none").unwrap(), Severity::None);
    }

    /// Regression test for Bug 1: non-interactive `add --package cargo/foo:patch`
    /// must produce `Entry { name: "cargo/foo", ... }`, not `Entry { name: "foo", ... }`.
    ///
    /// Before the fix, line 43 used `id.name()` which strips the ecosystem prefix.
    /// After the fix, it uses `id.display_name()` which preserves `"cargo/foo"`.
    /// In a polyglot workspace, the bare name `"foo"` is ambiguous and causes
    /// `AmbiguousName` errors during `callisto version`.
    #[test]
    fn non_interactive_add_entry_preserves_ecosystem_qualifier() {
        let id = PackageId::parse("cargo/foo").unwrap();
        // display_name() returns ecosystem-qualified form; name() returns bare name.
        // The fix ensures the Entry built in the non-interactive handler uses display_name().
        let entry = Entry {
            name: id.display_name(),
            severity: Severity::Patch,
        };
        assert_eq!(
            entry.name, "cargo/foo",
            "Entry.name must equal display_name(), not the bare name"
        );
    }

    /// Consecutive calls to generate_human_slug() must all produce distinct values,
    /// even when the OS clock resolution coalesces rapid calls to the same tick.
    #[test]
    fn test_generate_human_slug_consecutive_calls_differ() {
        let slugs: HashSet<String> = (0..50).map(|_| generate_human_slug()).collect();
        assert_eq!(
            slugs.len(),
            50,
            "expected 50 distinct slugs from 50 consecutive calls; got {} unique values",
            slugs.len()
        );
    }

    fn every_slug() -> HashSet<String> {
        let mut slugs = HashSet::new();
        for _ in 0..200_000 {
            slugs.insert(generate_human_slug());
            if slugs.len() == 8000 {
                break;
            }
        }
        assert_eq!(slugs.len(), 8000);
        slugs
    }

    #[test]
    fn an_existing_changeset_is_never_chosen_as_the_new_filename() {
        let dir = tempfile::tempdir().unwrap();
        let taken: Vec<String> = every_slug().into_iter().take(4000).collect();
        for slug in &taken {
            fs::write(dir.path().join(format!("{slug}.md")), "x").unwrap();
        }
        let chosen = unused_changeset_filename(dir.path()).unwrap();
        assert!(!dir.path().join(&chosen).exists(), "{chosen} already exists");
    }

    #[test]
    fn a_name_taken_after_it_was_chosen_is_skipped_and_the_other_changeset_survives() {
        let dir = tempfile::tempdir().unwrap();
        fs::write(dir.path().join("taken.md"), "someone else's").unwrap();
        let mut slugs = ["taken", "taken", "free"].into_iter().map(String::from);
        let chosen = create_changeset(dir.path(), "mine", &ApplyPermit::force_for_tests(), || {
            slugs.next().unwrap()
        })
        .unwrap();
        assert_eq!(chosen, "free.md");
        assert_eq!(
            fs::read_to_string(dir.path().join("taken.md")).unwrap(),
            "someone else's"
        );
        assert_eq!(fs::read_to_string(dir.path().join("free.md")).unwrap(), "mine");
    }

    #[test]
    fn a_directory_with_every_slug_taken_is_an_error_not_an_overwrite() {
        let dir = tempfile::tempdir().unwrap();
        for slug in every_slug() {
            fs::write(dir.path().join(format!("{slug}.md")), "x").unwrap();
        }
        assert!(matches!(
            unused_changeset_filename(dir.path()),
            Err(CliError::Io { .. })
        ));
    }

    #[test]
    fn a_changesets_directory_that_does_not_exist_yet_gives_a_filename() {
        let dir = tempfile::tempdir().unwrap();
        let missing = dir.path().join("not-created");
        assert!(unused_changeset_filename(&missing).unwrap().ends_with(".md"));
    }

    /// When a polyglot workspace contains `cargo/foo` and `npm/foo`, the
    /// interactive wizard's package-selection list must show two distinct,
    /// ecosystem-qualified names so the user can tell them apart.
    ///
    /// Fails before the fix (`.name()` produces two identical `"foo"` entries)
    /// and passes after the fix (`.display_name()` produces `"cargo/foo"` and
    /// `"npm/foo"`).
    #[test]
    fn polyglot_package_selection_names_are_distinct() {
        let packages = [make_package("cargo/foo"), make_package("npm/foo")];
        let names = collect_package_names(packages.iter());

        assert_eq!(names.len(), 2, "expected 2 entries; got {names:?}");
        assert!(
            names.contains(&"cargo/foo".to_string()),
            "expected ecosystem-qualified name 'cargo/foo'; got {names:?}"
        );
        assert!(
            names.contains(&"npm/foo".to_string()),
            "expected ecosystem-qualified name 'npm/foo'; got {names:?}"
        );
    }
}

