        }
    }

    #[test]
    fn handle_prints_root_help_with_no_command() {
        let result = handle(HelpArgs { command: vec![] }, &global());
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), ExitCode::SUCCESS);
    }

    #[test]
    fn handle_prints_subcommand_help() {
        let result = handle(
            HelpArgs {
                command: vec!["status".to_string()],
            },
            &global(),
        );
        assert!(result.is_ok());
        assert_eq!(result.unwrap(), ExitCode::SUCCESS);
    }

