38	/// The actual classification [`write_stdout`] applies, pulled out so a test
39	/// can exercise it against a real closed pipe without touching the
40	/// process's real (unredirectable, in-process) stdout fd.
41	fn write_swallowing_broken_pipe<W: Write>(w: &mut W, bytes: &[u8]) -> io::Result<()> {
42	    match w.write_all(bytes) {
43	        Ok(()) => Ok(()),
44	        Err(e) if e.kind() == io::ErrorKind::BrokenPipe => Ok(()),
45	        Err(e) => Err(e),
46	    }
47	}
48	
49	/// Writes one line (plus trailing newline) through [`write_stdout`].
50	pub fn emit_line(line: &str) -> io::Result<()> {
51	    write_stdout(format!("{line}\n").as_bytes())
52	}
53	
54	/// Writes one line to stderr -- for interactive wizard narration
55	/// (`callisto add`'s step prompts), which must stay off stdout so a script
56	/// piping stdout never sees prompt text mixed into a report or changeset preview.
57	pub fn prompt_line(line: &str) {
58	    eprintln!("{line}");
59	}
60	
61	pub fn log_line(format: OutputFormat, line: &str) -> io::Result<()> {
62	    match format {
63	        OutputFormat::Json => {
64	            eprintln!("{line}");
65	            Ok(())
66	        }
67	        OutputFormat::Text => emit_line(line),
68	    }
69	}
