71	#[cfg(test)]
72	mod tests {
73	    use callisto_model::{Diagnostic, Report};
74	    use serde::Deserialize;
75	
76	    use super::*;
77	
78	    #[derive(Serialize, Deserialize)]
79	    struct FakeReport {
80	        value: u32,
81	    }
82	
83	    impl callisto_model::Report for FakeReport {
84	        const COMMAND: &'static str = "fake-report";
85	
86	        fn schema_version(&self) -> u32 {
87	            1
88	        }
89	
90	        fn diagnostics(&self) -> &[Diagnostic] {
91	            &[]
92	        }
93	    }
94	
95	    #[test]
96	    fn write_json_serializes_pretty_with_trailing_newline() {
97	        let mut buf = Vec::new();
98	        write_json(&mut buf, &FakeReport { value: 42 }).unwrap();
99	        let text = String::from_utf8(buf).unwrap();
100	        assert!(text.contains("\"value\": 42"), "got:\n{text}");
101	        assert!(text.ends_with('\n'));
102	    }
103	
104	    #[test]
105	    fn emit_report_injects_command_schema_version_and_dry_run() {
106	        let mut buf = Vec::new();
107	        emit_report(&mut buf, &FakeReport { value: 7 }, false).unwrap();
108	        let text = String::from_utf8(buf).unwrap();
109	        assert!(text.contains("\"command\": \"fake-report\""), "got:\n{text}");
110	        assert!(text.contains("\"schemaVersion\": 1"), "got:\n{text}");
111	        assert!(text.contains("\"dryRun\": false"), "got:\n{text}");
112	        assert!(text.contains("\"value\": 7"), "got:\n{text}");
113	    }
114	
115	    /// The payload's own `schemaVersion` field must not survive alongside the
116	    /// envelope's -- exactly one `"schemaVersion"` key, not two.
117	    #[test]
118	    fn emit_report_does_not_duplicate_schema_version_key() {
119	        let mut buf = Vec::new();
120	        emit_report(&mut buf, &FakeReport { value: 1 }, true).unwrap();
121	        let text = String::from_utf8(buf).unwrap();
122	        assert_eq!(text.matches("\"schemaVersion\"").count(), 1, "got:\n{text}");
123	        assert!(text.contains("\"dryRun\": true"), "got:\n{text}");
124	    }
125	
126	    /// Against a *real* closed pipe (a `UnixStream` half whose peer was
127	    /// dropped, not a simulated error), the raw write must actually fail
128	    /// with `BrokenPipe` (positive proof this test exercises the real
129	    /// condition, not a vacuously-true no-op), and
130	    /// `write_swallowing_broken_pipe` -- the classification `write_stdout`
131	    /// applies to the real stdout fd -- must convert that into `Ok(())`
132	    /// rather than let it propagate (`println!`'s failure mode).
133	    #[cfg(unix)]
134	    #[test]
135	    fn write_swallowing_broken_pipe_converts_a_real_broken_pipe_to_ok() {
136	        use std::os::unix::net::UnixStream;
137	
138	        let (mut writer, reader) = UnixStream::pair().expect("create socket pair");
139	        drop(reader);
140	
141	        // The peer's close is not always visible to the very first write, so keep writing until
142	        // the broken pipe surfaces.
143	        let raw_err = (0..64)
144	            .find_map(|_| writer.write_all(&[0u8; 4096]).err())
145	            .expect("writing to a closed UnixStream peer must fail");
146	        assert_eq!(
147	            raw_err.kind(),
148	            io::ErrorKind::BrokenPipe,
149	            "test setup must reproduce a real BrokenPipe, got: {raw_err:?}"
150	        );
151	
152	        let result = write_swallowing_broken_pipe(&mut writer, b"more data after the pipe broke");
153	        assert!(result.is_ok(), "must swallow BrokenPipe, got: {result:?}");
154	    }
155	
156	    /// A non-`BrokenPipe` I/O error must still propagate -- this isn't a
157	    /// blanket "ignore every write error", only the closed-pipe case.
158	    #[test]
159	    fn write_swallowing_broken_pipe_propagates_other_errors() {
160	        struct AlwaysFails;
161	        impl Write for AlwaysFails {
162	            fn write(&mut self, _buf: &[u8]) -> io::Result<usize> {
163	                Err(io::Error::new(io::ErrorKind::PermissionDenied, "nope"))
164	            }
165	            fn flush(&mut self) -> io::Result<()> {
166	                Ok(())
167	            }
168	        }
169	
170	        let result = write_swallowing_broken_pipe(&mut AlwaysFails, b"data");
171	        assert_eq!(
172	            result.unwrap_err().kind(),
173	            io::ErrorKind::PermissionDenied,
174	            "a non-BrokenPipe error must still propagate"
175	        );
176	    }
177	
178	    /// No source file under `callisto-cli/src` may call the raw `println!`
179	    /// macro outside a `#[cfg(test)]` module: it panics on a closed stdout
180	    /// (`BrokenPipe`) instead of exiting quietly, unlike
181	    /// [`write_stdout`]/[`emit_line`]. `eprintln!` (stderr) is unaffected.
182	    #[test]
183	    fn println_macro_is_banned_outside_test_modules() {
184	        let src_dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src");
185	        let mut offenders = Vec::new();
186	        visit_rs_files(&src_dir, &mut offenders);
187	        assert!(
188	            offenders.is_empty(),
189	            "println! is banned in callisto-cli/src outside #[cfg(test)] modules; use \
190	             output::write_stdout/emit_line instead. Offending locations:\n{}",
191	            offenders.join("\n")
192	        );
193	    }
194	
195	    fn visit_rs_files(dir: &std::path::Path, offenders: &mut Vec<String>) {
196	        for entry in std::fs::read_dir(dir).expect("read_dir").flatten() {
197	            let path = entry.path();
198	            if path.is_dir() {
199	                visit_rs_files(&path, offenders);
200	            } else if path.extension().is_some_and(|ext| ext == "rs") {
201	                check_file_for_bare_println(&path, offenders);
202	            }
203	        }
204	    }
205	
206	    /// Scans only the portion of the file before its first `#[cfg(test)]`
207	    /// module (every file in this crate puts its test module last), skips
208	    /// comment lines (this very file's doc comments mention `println!` by
209	    /// name), and flags a `println!` call that is not part of `eprintln!`.
210	    fn check_file_for_bare_println(path: &std::path::Path, offenders: &mut Vec<String>) {
211	        let text = std::fs::read_to_string(path).expect("read source file");
212	        let scope = text.split("#[cfg(test)]").next().unwrap_or(&text);
213	        for (i, line) in scope.lines().enumerate() {
214	            if line.trim_start().starts_with("//") {
215	                continue;
216	            }
217	            let mut search_from = 0;
218	            while let Some(pos) = line[search_from..].find("println!") {
219	                let idx = search_from + pos;
220	                let preceded_by_e = idx > 0 && line.as_bytes()[idx - 1] == b'e';
221	                if !preceded_by_e {
222	                    offenders.push(format!("{}:{}: {}", path.display(), i + 1, line.trim()));
223	                }
224	                search_from = idx + "println!".len();
225	            }
226	        }
227	    }
228	
229	    #[test]
230	    fn report_trait_accessors_expose_schema_version_and_diagnostics() {
231	        let report = FakeReport { value: 1 };
232	        assert_eq!(report.schema_version(), 1);
233	        assert!(report.diagnostics().is_empty());
234	    }
235	
236	    /// `log_line` routes purely by `OutputFormat` (Json -> stderr, Text ->
237	    /// stdout); it writes directly to the process's real fds rather than a
238	    /// caller-supplied writer, so its destination isn't capturable in-process.
239	    /// This exercises both branches to prove neither panics.
240	    #[test]
241	    fn log_line_does_not_panic_for_either_output_format() {
242	        log_line(OutputFormat::Json, "to stderr").unwrap();
243	        log_line(OutputFormat::Text, "to stdout").unwrap();
244	    }
245	}
